import{z as d,x as A,o as l,c as B,q as r,j as s,D as E,d as t,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"掩模遮挡刀片 REMA","description":"","frontmatter":{"title":"掩模遮挡刀片 REMA","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-masking-blades.md","filePath":"litho/reticle-masking-blades.md","lastUpdated":1791413859000}'),p={name:"litho/reticle-masking-blades.md"};function D(m,a,h,c,f,u){const i=A("Mermaid");return l(),B("div",null,[a[2]||(a[2]=r('<h1 id="掩模遮挡刀片-rema" tabindex="-1">掩模遮挡刀片 REMA <a class="header-anchor" href="#掩模遮挡刀片-rema" aria-label="Permalink to &quot;掩模遮挡刀片 REMA&quot;">​</a></h1><div class="epigraph"><p>REMA 刀片挡住不该曝光的掩模区：划片槽、邻场、条码。它切的是场，不是光瞳。</p><footer>—— 对照 reticle masking blades 在扫描投影机上的公开功能</footer></div><p><a href="/litho/homogenizer-fly-eye">上一课</a>给出满场均匀照明。缺口是：掩模上并非处处要印。REMA（reticle masking）刀片在掩模附近挡光，定义曝光矩形。与 <a href="/litho/slit-scan-average">狭缝</a> 分工：狭缝是扫描瞬时开口，刀片是这场用哪一块掩模。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模版上有对准标记、邻 die、 Pellicle 边。若整版照明，边缘图形和金属边会印到晶圆或产生杂散。刀片误差直接是场尺寸与边缘剂量梯度。把场边缘 CD 异常全写成镜头畸变，会漏掉刀片半影。</p><p><span class="marginnote">术语翻译：REMA 就是一组可电动进退的「遮光刀片」，像照相机的取景框，把曝光限制在掩模上真正要印的矩形里。它管「照到版上哪一块」，与管「光从哪些角度照」的光瞳整形完全是两回事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四刀（或等效）围出矩形，随扫描与场尺寸改。半影宽度由刀片离焦与照明 σ 决定，边缘有一段剂量斜坡，小图形不要贴刀片。配方：场大小、刀片余量、是否挡标记。</p>',8)),(l(),s(n,null,{default:E(()=>[o(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILL%5B%22%E5%9D%87%E5%85%89%E7%85%A7%E6%98%8E%22%5D%20--%3E%20BL%5B%22REMA%20%E5%88%80%E7%89%87%22%5D%0A%20%20BL%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%E7%9F%A9%E5%BD%A2%22%5D%0A%20%20SLIT%5B%22%E6%89%AB%E6%8F%8F%E7%8B%AD%E7%BC%9D%22%5D%20--%3E%20EXP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"刀片在物面附近，光瞳整形在照明光瞳。调刀片不会把偶极变成环形；调光瞳不会切场。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"刀片是几何挡光。衍射在刃口产生半影，高 σ 半影更软。扫描方向上狭缝已经限制瞬时场，刀片主要管静态场边界与非扫描边。",-1)),(l(),s(n,null,{default:E(()=>[o(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E5%88%80%E7%89%87%E5%88%83%E5%8F%A3%22%5D%20--%3E%20DIFF%5B%22%E5%88%83%E5%8F%A3%E8%A1%8D%E5%B0%84%22%5D%0A%20%20DIFF%20--%3E%20PEN%5B%22%E5%8D%8A%E5%BD%B1%3A%20%E8%BE%B9%E7%BC%98%E5%89%82%E9%87%8F%E6%96%9C%E5%9D%A1%22%5D%0A%20%20SIGMA%5B%22%E7%85%A7%E6%98%8E%20%CF%83%20%E5%A4%A7%22%5D%20--%3E%20SOFT%5B%22%E5%8D%8A%E5%BD%B1%E6%9B%B4%E8%BD%AF%E6%9B%B4%E5%AE%BD%22%5D%0A%20%20DEFOC%5B%22%E5%88%80%E7%89%87%E7%A6%BB%E7%84%A6%E9%87%8F%22%5D%20--%3E%20PEN%0A%20%20PEN%20--%3E%20NEAREDGE%5B%22%E8%B4%B4%E8%BE%B9%E5%B0%8F%E5%9B%BE%E5%BD%A2%E5%90%83%E5%89%82%E9%87%8F%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20NEAREDGE%20--%3E%20RULE%5B%22%E9%85%8D%E6%96%B9%3A%20%E5%9C%BA%E5%86%85%E7%95%99%E5%88%80%E7%89%87%E4%BD%99%E9%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课照明均匀性沿狭缝的测量，假定刀片已张开到配方场。</p><p><span class="marginnote">直觉类比：半影像影子边缘——手电筒离墙越远、灯罩面越大，影子边越糊。刀片离焦量与照明 σ 扮演「离墙距离」与「光源大小」，这就是「小图形不要贴刀片」的物理来源。</span></p><p><span class="marginnote">常见误区：场边缘 CD 异常就归镜头畸变。刀片半影让边缘一小段处在剂量斜坡上，症状相似——判别法是把场尺寸改一档再看：随刀片动的是半影，随场位置动的才是畸变。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REMA 切掩模场，狭缝切扫描瞬时开口。</li><li>刃口半影是边缘 CD 源。</li><li>出处：扫描投影机遮挡通识；狭缝课。</li></ul>',6))])}const F=d(p,[["render",D]]);export{b as __pageData,F as default};
